type Device = {
  deviceId: string;
  name: string;
  profile: string;
  lastSeenAt: string;
  uptimeSeconds: number;
  eventsPublished: number;
  faults: number;
};

const devices = input.devices as Device[];

const duration = (seconds: number): string => {
  const total = Math.max(Math.round(seconds), 0);
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const rest = total % 60;
  if (hours > 0) return hours + "h " + minutes + "m " + rest + "s";
  if (minutes > 0) return minutes + "m " + rest + "s";
  return rest + "s";
};

const sum = (values: number[]): number => values.reduce((total, value) => total + value, 0);

const faulted = devices.filter((device) => device.faults > 0);

// One point per profile, events summed within it.
const byProfile = new Map<string, number>();
// Uptime summed per profile for the pie chart.
const uptimeByProfile = new Map<string, number>();
for (const device of devices) {
  byProfile.set(device.profile, (byProfile.get(device.profile) ?? 0) + device.eventsPublished);
  uptimeByProfile.set(device.profile, (uptimeByProfile.get(device.profile) ?? 0) + device.uptimeSeconds);
}

return {
  title: input.reportTitle,
